// Quote references look like UDN-2611-K7QMX: year+month (IST) and five
// characters from an alphabet without 0/O or 1/I/L. Generated by the
// database (private.new_reference); validated here for user input.

export const REFERENCE_PATTERN = /^UDN-\d{4}-[2-9A-HJKMNP-Z]{5}$/;

/** Accepts "udn 2611 k7qmx", "UDN-2611-K7QMX", " UDN_2611_K7QMX "; returns the canonical form or null. */
export function normalizeReference(input: string): string | null {
  const compact = input.trim().toUpperCase().replace(/[\s_]+/g, "-").replace(/-+/g, "-");
  const m = /^UDN-?(\d{4})-?([A-Z0-9]{5})$/.exec(compact);
  if (!m) return null;
  const ref = `UDN-${m[1]}-${m[2]}`;
  return REFERENCE_PATTERN.test(ref) ? ref : null;
}

export const REFERENCE_HELP =
  "Quote references look like UDN-2611-K7QMX. You can find yours in the confirmation email or in your Udan account.";
